<?php
require __DIR__.'/includes/bootstrap.php';require_auth();require __DIR__.'/includes/layout.php';require __DIR__.'/includes/data.php';
if($_SERVER['REQUEST_METHOD']==='POST'){
    require_permission('receiving.create');verify_csrf();$product=(int)($_POST['product_id']??0);$branch=(int)($_POST['branch_id']??0);$brand=(int)($_POST['brand_id']??0);$qty=(float)($_POST['quantity']??0);$cost=(float)($_POST['unit_cost']??0);$date=$_POST['date']??date('Y-m-d');$notes=trim((string)($_POST['notes']??''));
    if(!$product||!$branch||!$brand||$qty<=0||$cost<0){flash('error','Choose branch, brand and raw item, then enter valid quantity and unit cost.');redirect('receiving.php?action=create');}
    if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||$date>date('Y-m-d')){flash('error','Choose a valid receiving date that is not in the future.');redirect('receiving.php?action=create');}
    try{enforce_branch_scope($branch);$pdo->beginTransaction();$p=$pdo->prepare('SELECT p.name,u.symbol FROM products p JOIN units u ON u.id=p.unit_id WHERE p.id=? AND p.status="active" AND p.deleted_at IS NULL');$p->execute([$product]);$item=$p->fetch();if(!$item)throw new RuntimeException('The selected raw item is unavailable.');$total=round($qty*$cost,2);$ref=next_reference($pdo,'RCV','stock_receivings');$s=$pdo->prepare('INSERT INTO stock_receivings(reference_no,received_date,branch_id,brand_id,supplier_id,invoice_no,total_cost,notes,created_by) VALUES(?,?,?,?,NULL,"",?,?,?)');$s->execute([$ref,$date,$branch,$brand,$total,$notes,user()['id']]);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO stock_receiving_items(receiving_id,product_id,quantity,unit_cost,line_total) VALUES(?,?,?,?,?)')->execute([$id,$product,$qty,$cost,$total]);ledger($pdo,['product_id'=>$product,'branch_id'=>$branch,'brand_id'=>$brand,'transaction_type'=>'receiving','reference_type'=>'receiving','reference_id'=>$id,'reference_no'=>$ref,'quantity_in'=>$qty,'quantity_out'=>0,'notes'=>$notes]);audit($pdo,'create','receiving',$id,null,['item'=>$item['name'],'quantity'=>$qty,'unit'=>$item['symbol'],'unit_cost'=>$cost]);$pdo->commit();flash('success',number_format($qty,3).' '.$item['symbol'].' of '.$item['name'].' received. Available stock updated.');redirect('receiving.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());redirect('receiving.php?action=create');}
}
$create=($_GET['action']??'')==='create';render_header('Received Stock','receiving');page_title('Received Stock','RAW ITEM RECEIVING','Add purchased raw items using only branch, brand, quantity and unit cost.',$create?'':'Receive Raw Item',app_url('receiving.php?action=create'));
if($create):$branches=options($pdo,'branches');$brands=options($pdo,'brands');$products=$pdo->query('SELECT p.id,CONCAT(p.name," · ",u.symbol) label,u.symbol FROM products p JOIN units u ON u.id=p.unit_id WHERE p.status="active" AND p.deleted_at IS NULL ORDER BY p.name')->fetchAll();?>
<article class="card form-card receive-simple"><div class="card-head"><div><h2>Receive a raw item</h2><small>The available stock balance updates automatically.</small></div><span class="status">5 SIMPLE FIELDS</span></div><?php if(!$products):?><div class="form-alert">Add a raw item before receiving stock.</div><a class="btn primary" href="<?=app_url('products.php?action=create')?>">Add First Raw Item</a><?php else:?><form method="post" data-receiving-form><?=csrf_field()?><div class="form-grid"><label>Date<input type="date" name="date" value="<?=date('Y-m-d')?>" max="<?=date('Y-m-d')?>" required></label><label>Branch *<select name="branch_id" required><option value="">Choose branch</option><?php foreach($branches as $x):?><option value="<?=$x['id']?>"><?=e($x['label'])?></option><?php endforeach;?></select></label><label>Brand *<select name="brand_id" required><option value="">Choose brand</option><?php foreach($brands as $x):?><option value="<?=$x['id']?>"><?=e($x['label'])?></option><?php endforeach;?></select></label><label>Raw Item *<select name="product_id" required><option value="">Choose raw item</option><?php foreach($products as $x):?><option value="<?=$x['id']?>" data-unit="<?=e($x['symbol'])?>"><?=e($x['label'])?></option><?php endforeach;?></select></label><label>Quantity *<div class="input-with-unit"><input type="number" name="quantity" inputmode="decimal" min="0.001" step="0.001" required placeholder="0"><span data-receive-unit>unit</span></div></label><label>Unit Cost (QAR) *<input type="number" name="unit_cost" inputmode="decimal" min="0" step="0.01" required placeholder="0.00"></label><label class="full">Note (optional)<textarea name="notes" rows="2" placeholder="Optional receiving note"></textarea></label></div><div class="receive-total"><span>Receiving total</span><b data-receive-total>QAR 0.00</b></div><div class="form-actions"><a class="btn" href="<?=app_url('receiving.php')?>">Cancel</a><button class="btn primary"><i data-icon="inbox"></i>Save Received Stock</button></div></form><?php endif;?></article>
<?php else:[$period,$from,$to,$branch,$brand]=page_params();$where=['r.received_date BETWEEN ? AND ?','r.deleted_at IS NULL'];$args=[$from,$to];if($branch){$where[]='r.branch_id=?';$args[]=$branch;}if($brand){$where[]='r.brand_id=?';$args[]=$brand;}$s=$pdo->prepare('SELECT r.reference_no,r.received_date,r.total_cost,r.notes,ri.quantity,ri.unit_cost,p.name product,u.symbol,b.name branch,br.name brand,usr.name entered_by FROM stock_receivings r JOIN stock_receiving_items ri ON ri.receiving_id=r.id JOIN products p ON p.id=ri.product_id JOIN units u ON u.id=p.unit_id JOIN branches b ON b.id=r.branch_id JOIN brands br ON br.id=r.brand_id JOIN users usr ON usr.id=r.created_by WHERE '.implode(' AND ',$where).' ORDER BY r.id DESC LIMIT 100');$s->execute($args);$rows=$s->fetchAll();?>
<div class="page-head" style="margin-top:-8px"><div></div><?php filter_bar($pdo);?></div><article class="card table-card"><div class="table-toolbar"><div><b><?=count($rows)?> received entries</b><small style="display:block;color:var(--muted);margin-top:4px">Raw-item receiving history</small></div><input placeholder="Search received items…" data-table-search></div><div class="table-wrap"><table><thead><tr><th>Raw Item</th><th>Date</th><th>Branch / Brand</th><th>Quantity</th><th>Unit Cost</th><th>Total Cost</th><th>Entered By</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td data-label="Raw Item"><b><?=e($row['product'])?></b><small style="display:block;color:var(--muted)"><?=e($row['reference_no'])?></small></td><td data-label="Date"><?=date('d M Y',strtotime($row['received_date']))?></td><td data-label="Branch / Brand"><?=e($row['branch'])?> · <?=e($row['brand'])?></td><td data-label="Quantity"><b><?=number_format($row['quantity'],3).' '.e($row['symbol'])?></b></td><td data-label="Unit Cost"><?=money($row['unit_cost'])?></td><td data-label="Total Cost"><b><?=money($row['total_cost'])?></b></td><td data-label="Entered By"><?=e($row['entered_by'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7"><div class="empty"><div class="empty-icon"><i data-icon="inbox"></i></div>No received stock in this period.</div></td></tr><?php endif;?></tbody></table></div></article><?php endif;render_footer('receiving');
